/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.alt;

import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicReference;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.feature.oauth.client.domain.ClientAuthMethod;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.client.domain.RedirectUriPolicy;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/**
 * Clients of the OAuth flow tests, all with {@link OidcTestFixtures#CLIENT_SECRET}:
 * <ul>
 * <li>{@link OidcTestFixtures#CLIENT_ID} in {@link OidcTestFixtures#TENANT} and
 * {@link OidcTestFixtures#OTHER_TENANT}: confidential and public at once, without a registered auth
 * method (any secret method is accepted);</li>
 * <li>{@link OidcTestFixtures#WEB_CLIENT_ID}: confidential web app registered for
 * client_secret_basic, without public access;</li>
 * <li>{@link OidcTestFixtures#SPA_CLIENT_ID}: public client registered for none.</li>
 * </ul>
 * All of them register {@link OidcTestFixtures#REDIRECT_URI} (exact match) and may request tokens
 * for {@link OidcTestFixtures#API_AUDIENCE}.
 */
@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class FixedClientStoreGateway implements ClientStoreGateway {
  /**
   * Registered redirects, checked with the production {@link RedirectUriPolicy}.
   */
  private static final List<String> REDIRECTS = List.of(OidcTestFixtures.REDIRECT_URI);
  private final AtomicReference<List<String>> allowedRedirects = new AtomicReference<>(REDIRECTS);
  private final AtomicReference<List<String>> allowedScopes = new AtomicReference<>();
  private final AtomicReference<List<String>> allowedGrants = new AtomicReference<>();
  private final AtomicReference<List<String>> clientCredentialsScopes = new AtomicReference<>();
  private final AtomicReference<List<String>> allowedResponseTypes = new AtomicReference<>();
  private volatile boolean requirePar;
  private volatile String jwksJson;
  private volatile boolean pairwise;
  private volatile java.util.function.UnaryOperator<ClientDetails.ClientDetailsBuilder> customizer =
      builder -> builder;

  @PostConstruct
  void init() {
    reset();
  }

  public void setAllowedScopes(List<String> scopes) {
    allowedScopes.set(List.copyOf(scopes));
  }

  public void setAllowedGrants(List<String> grants) {
    allowedGrants.set(List.copyOf(grants));
  }

  public void setClientCredentialsScopes(List<String> scopes) {
    clientCredentialsScopes.set(List.copyOf(scopes));
  }

  public void setAllowedResponseTypes(List<String> types) {
    allowedResponseTypes.set(List.copyOf(types));
  }

  public void setAllowedRedirects(List<String> redirects) {
    allowedRedirects.set(List.copyOf(redirects));
  }

  public void setRequirePar(boolean required) {
    requirePar = required;
  }

  /**
   * Registers extra metadata on every test client (encryption, signing, DPoP...).
   */
  public void customize(java.util.function.UnaryOperator<ClientDetails.ClientDetailsBuilder> how) {
    customizer = how;
  }

  public void setPairwise(boolean pairwiseSubject) {
    pairwise = pairwiseSubject;
  }

  public void setJwksJson(String jwks) {
    jwksJson = jwks;
  }

  public void reset() {
    allowedScopes.set(List.of("*"));
    allowedGrants.set(List.of("authorization_code", "password", "refresh_token", "form",
        "client_credentials", "mfa", "urn:ietf:params:oauth:grant-type:device_code",
        "urn:ietf:params:oauth:grant-type:token-exchange"));
    clientCredentialsScopes.set(List.of("orders:read", "orders:write"));
    allowedResponseTypes.set(List.of("code"));
    allowedRedirects.set(REDIRECTS);
    requirePar = false;
    jwksJson = null;
    pairwise = false;
    customizer = builder -> builder;
  }

  @Override
  public Optional<ClientDetails> loadPreautorized(String tenant, String clientId) {
    return method(tenant, clientId).map(_ -> buildClient(clientId, true));
  }

  @Override
  public Optional<ClientDetails> loadForAuthorization(String tenant, String clientId,
      String redirect) {
    boolean redirectAllowed = RedirectUriPolicy.allows(allowedRedirects.get(), redirect);
    return redirectAllowed
        ? method(tenant, clientId).map(_ -> buildClient(clientId, !isSpa(clientId)))
        : Optional.empty();
  }

  @Override
  public Optional<ClientDetails> loadPublicById(String tenant, String clientId) {
    return method(tenant, clientId).filter(_ -> !isWeb(clientId) && !isJwt(clientId))
        .map(_ -> buildClient(clientId, false));
  }

  @Override
  public Optional<ClientDetails> loadForAssertion(String tenant, String clientId) {
    return method(tenant, clientId).filter(_ -> isJwt(clientId))
        .map(_ -> buildClient(clientId, true));
  }

  @Override
  public Optional<ClientDetails> loadPrivate(String tenant, String clientId, String clientSecret) {
    boolean secretMatches = OidcTestFixtures.CLIENT_SECRET.equals(clientSecret);
    return secretMatches ? method(tenant, clientId).map(_ -> buildClient(clientId, true))
        .filter(client -> !isJwt(clientId)) : Optional.empty();
  }

  /**
   * The client registered in the tenant; the value is unused, only its presence matters.
   */
  private Optional<String> method(String tenant, String clientId) {
    if (OidcTestFixtures.CLIENT_ID.equals(clientId)) {
      return OidcTestFixtures.TENANT.equals(tenant) || OidcTestFixtures.OTHER_TENANT.equals(tenant)
          ? Optional.of(clientId)
          : Optional.empty();
    }
    return OidcTestFixtures.TENANT.equals(tenant)
        && (isWeb(clientId) || isSpa(clientId) || isJwt(clientId)) ? Optional.of(clientId)
            : Optional.empty();
  }

  private static boolean isWeb(String clientId) {
    return OidcTestFixtures.WEB_CLIENT_ID.equals(clientId);
  }

  private static boolean isJwt(String clientId) {
    return OidcTestFixtures.JWT_CLIENT_ID.equals(clientId);
  }

  private static boolean isSpa(String clientId) {
    return OidcTestFixtures.SPA_CLIENT_ID.equals(clientId);
  }

  private ClientDetails buildClient(String clientId, boolean confidential) {
    ClientAuthMethod registered = isWeb(clientId) ? ClientAuthMethod.CLIENT_SECRET_BASIC
        : isSpa(clientId) ? ClientAuthMethod.NONE
            : isJwt(clientId) ? ClientAuthMethod.PRIVATE_KEY_JWT : null;
    return customizer.apply(ClientDetails.builder().clientId(clientId)
        .allowedScopes(allowedScopes.get()).clientCredentialsScopes(clientCredentialsScopes.get())
        .allowedResponseTypes(allowedResponseTypes.get()).allowedGrants(allowedGrants.get())
        .requirePar(requirePar).jwksJson(jwksJson).protectedWithSecret(confidential)
        .tokenEndpointAuthMethod(registered).requirePkce(isSpa(clientId))
        .allowedAudiences(List.of(OidcTestFixtures.API_AUDIENCE, OidcTestFixtures.RESOURCE_URI))
        .introspectionAllowed(OidcTestFixtures.CLIENT_ID.equals(clientId))
        .allowedRedirectUris(allowedRedirects.get()).pairwiseSubject(pairwise)
        .postLogoutRedirectUris(List.of(OidcTestFixtures.POST_LOGOUT_URI))).build();
  }
}
